class Solution:
    def maxSubsequence(self, nums: list[int], k: int) -> list[int]:
        indexed = [(val, idx) for idx, val in enumerate(nums)]
        top_k = sorted(indexed, key=lambda x: x[0], reverse=True)[:k]
        top_k.sort(key=lambda x: x[1])
        return [val for val, idx in top_k]

#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<int> maxSubsequence(std::vector<int>& nums, int k) {
        std::vector<std::pair<int, int>> indexed;
        for (int i = 0; i < (int)nums.size(); ++i) {
            indexed.push_back({nums[i], i});
        }
        std::sort(indexed.begin(), indexed.end(), [](const auto& a, const auto& b) {
            return a.first > b.first;
        });
        std::vector<std::pair<int, int>> topK(indexed.begin(), indexed.begin() + k);
        std::sort(topK.begin(), topK.end(), [](const auto& a, const auto& b) {
            return a.second < b.second;
        });
        std::vector<int> ans;
        for (const auto& p : topK) ans.push_back(p.first);
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] maxSubsequence(int[] nums, int k) {
        int[][] indexed = new int[nums.length][2];
        for (int i = 0; i < nums.length; i++) {
            indexed[i][0] = nums[i];
            indexed[i][1] = i;
        }

        Arrays.sort(indexed, (a, b) -> Integer.compare(b[0], a[0]));
        int[][] topK = Arrays.copyOf(indexed, k);
        Arrays.sort(topK, Comparator.comparingInt(a -> a[1]));

        int[] ans = new int[k];
        for (int i = 0; i < k; i++) ans[i] = topK[i][0];
        return ans;
    }
}

/**
 * @param {number[]} nums
 * @param {number} k
 * @return {number[]}
 */
var maxSubsequence = function(nums, k) {
    const indexed = nums.map((val, idx) => ({ val, idx }));
    indexed.sort((a, b) => b.val - a.val);
    const topK = indexed.slice(0, k);
    topK.sort((a, b) => a.idx - b.idx);
    return topK.map(x => x.val);
};
